import { MakeLogicType, actions, kea, path, reducers, selectors } from 'kea'

/** Where a run is executing: in the user's terminal, or on our infrastructure. */
export type WizardSyncMode = 'cloud' | 'local'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wizardSyncUiLogicValues {
    dialogOpen: boolean
    dismissedKey: string | null
    inlineCloudPanelMounted: boolean
    inlineLocalPanelMounted: boolean
    inlinePanelCounts: Record<WizardSyncMode, number>
    inlinePanelMounted: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wizardSyncUiLogicActions {
    claimInlinePanel: (mode: WizardSyncMode) => {
        mode: WizardSyncMode
    }
    closeDialog: () => {
        value: true
    }
    dismiss: (key: string) => {
        key: string
    }
    openDialog: () => {
        value: true
    }
    releaseInlinePanel: (mode: WizardSyncMode) => {
        mode: WizardSyncMode
    }
    restore: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface wizardSyncUiLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        inlineCloudPanelMounted: (inlinePanelCounts: Record<WizardSyncMode, number>) => boolean
        inlineLocalPanelMounted: (inlinePanelCounts: Record<WizardSyncMode, number>) => boolean
        inlinePanelMounted: (inlineCloudPanelMounted: boolean, inlineLocalPanelMounted: boolean) => boolean
    }
}

export type wizardSyncUiLogicType = MakeLogicType<
    wizardSyncUiLogicValues,
    wizardSyncUiLogicActions,
    Record<string, any>,
    wizardSyncUiLogicMeta
>

/**
 * UI state for the detached wizard sync widget, shared app-wide (mounted by WizardSyncFab):
 *   - `dismissedKey`: the run the user minimized. Keyed by run id (cloud) or session id (local) so a
 *     fresh run is never born already-minimized, and a minimize survives navigation (persisted).
 *   - `dialogOpen`: whether the "all the details" dialog is showing.
 *   - `inlineCloudPanelMounted` / `inlineLocalPanelMounted`: a scene is already showing a run inline
 *     (the onboarding install step, the inbox), so the detached surface for *that* run stands down
 *     rather than showing it twice. Refcounted: a boolean would let one panel's unmount un-hide the
 *     widget while another is still showing. Tracked per mode because cloud and local runs can be in
 *     flight at once, and a surface that only ever renders one of them must not silence the other.
 *
 * The widget itself owns no run data; the per-mode inner components feed it the normalized progress.
 */
export const wizardSyncUiLogic = kea<wizardSyncUiLogicType>([
    path(['scenes', 'onboarding', 'wizardSyncUiLogic']),
    actions({
        dismiss: (key: string) => ({ key }),
        restore: true,
        openDialog: true,
        closeDialog: true,
        claimInlinePanel: (mode: WizardSyncMode) => ({ mode }),
        releaseInlinePanel: (mode: WizardSyncMode) => ({ mode }),
    }),
    reducers({
        dismissedKey: [
            null as string | null,
            { persist: true },
            {
                dismiss: (_, { key }) => key,
                restore: () => null,
            },
        ],
        dialogOpen: [
            false,
            {
                openDialog: () => true,
                closeDialog: () => false,
                restore: () => false,
            },
        ],
        inlinePanelCounts: [
            { cloud: 0, local: 0 } as Record<WizardSyncMode, number>,
            {
                claimInlinePanel: (state, { mode }) => ({ ...state, [mode]: state[mode] + 1 }),
                releaseInlinePanel: (state, { mode }) => ({ ...state, [mode]: Math.max(0, state[mode] - 1) }),
            },
        ],
    }),
    selectors({
        inlineCloudPanelMounted: [
            (s) => [s.inlinePanelCounts],
            (inlinePanelCounts: Record<WizardSyncMode, number>): boolean => inlinePanelCounts.cloud > 0,
        ],
        inlineLocalPanelMounted: [
            (s) => [s.inlinePanelCounts],
            (inlinePanelCounts: Record<WizardSyncMode, number>): boolean => inlinePanelCounts.local > 0,
        ],
        /** Any run is shown inline — for surfaces that don't distinguish which one, like the nav item. */
        inlinePanelMounted: [
            (s) => [s.inlineCloudPanelMounted, s.inlineLocalPanelMounted],
            (inlineCloudPanelMounted: boolean, inlineLocalPanelMounted: boolean): boolean =>
                inlineCloudPanelMounted || inlineLocalPanelMounted,
        ],
    }),
])
